#include <iostream>
#include <string>

int parse_count(const std::string& text) {
    if (text.empty()) return 0;
    int value = 0;
    for (char ch : text) {
        if (ch < '0' || ch > '9') return -1;
        value = value * 10 + (ch - '0');
    }
    return value;
}
int main() { std::cout << parse_count("123") << ' ' << parse_count("12x") << '\n'; }
